-- ============================================================================
-- ESTANCIA NUEVA SPORT · TIENDA — ROLLBACK de IMPORT_TIENDA.sql
-- Business 40b0fa9d-9ce6-4e17-902d-6f5f37cc58ab
--
-- ⚠ ARCHIVO GENERADO por build_import_tienda.py desde _tpl_rollback_tienda.sql.
-- ============================================================================
--
-- Borra los 353 artículos de la lista (por sku = código), sus insumos y las
-- categorías de la carga que queden vacías. NO borra el menú ni la bodega, NO
-- regresa inventory_mode, y NO toca lo que la tienda ya tenía antes.
--
-- ⚠ ABORTA si algún artículo ya se vendió, o si algún insumo ya tiene
--   movimientos, está en un conteo o en una receta, o lo usa otro producto.
-- ============================================================================

begin;

create temp table _tie_codigos (codigo text primary key) on commit drop;

insert into _tie_codigos (codigo)
select unnest(string_to_array(
  '1224,110000100497,097512510264,110000100718,1223,110000100420,110000100421,110000100424,110000100428,110000100649,766871822508,1052,1069,110000100463,110000100726,110000100427,1105,1108,1238,1228,110000100419,887768339241,110000100488,1229,110000100486,110000100485,110000100487,110000100484,110000100482,110000100489,110000100490,110000100418,110000100515,110000100414,110000100417,110000100413,110000100514,110000100415,110000100416,110000100483,110000100524,110000100422,110000100423,1226,1227,8435536789372,097512831048,1107,1124,1106,6165010781128,6165010781050,6165010781111,8435536788504,110000100001,110000100375,110000100002,110000100003,110000100376,110000100004,110000100005,110000100006,110000100007,110000100008,1066,110000100010,110000100011,110000100012,110000100013,110000100014,110000100015,110000100009,110000100016,110000100017,110000100018,110000100019,110000100382,110000100020,110000100021,110000100022,110000100023,110000100024,110000100025,110000100026,110000100027,110000100028,110000100029,110000100030,110000100031,110000100032,110000100033,110000100383,110000100405,110000100406,110000100035,110000100036,110000100037,110000100034,110000100536,110000100038,110000100039,110000100537,110000100538,110000100221,110000100224,110000100223,110000100222,110000100225,110000100228,110000100227,110000100226,110000100539,110000100040,110000100041,110000100042,110000100043,110000100044,110000100045,110000100046,110000100047,110000100403,110000100402,110000100401,110000100404,110000100397,110000100398,110000100399,110000100400,110000100048,110000100246,110000100049,110000100050,110000100051,110000100052,110000100053,110000100054,110000100055,110000100056,110000100057,1073,1074,1075,110000100058,110000100059,110000100061,110000100062,110000100395,110000100396,110000100063,110000100381,110000100064,110000100065,110000100066,110000100067,110000100068,110000100069,110000100070,110000100071,110000100072,110000100073,110000100074,110000100407,110000100408,110000100377,110000100378,110000100075,110000100076,110000100077,110000100078,110000100079,110000100080,110000100081,110000100082,110000100083,110000100084,110000100085,110000100086,110000100087,110000100380,110000100379,110000100088,110000100089,110000100090,110000100091,110000100092,110000100093,110000100094,110000100095,110000100096,110000100097,110000100098,110000100099,110000100100,110000100411,110000100101,110000100102,110000100103,110000100104,110000100105,110000100106,110000100107,110000100108,110000100109,110000100110,110000100111,110000100112,110000100113,110000100114,110000100409,110000100410,110000100115,110000100116,110000100268,110000100117,110000100118,110000100249,110000100248,110000100247,110000100715,110000100119,110000100120,110000100121,110000100122,110000100123,110000100124,1131,1130,1213,110000100125,110000100126,110000100127,110000100128,110000100129,110000100130,110000100131,110000100132,110000100250,1208,110000100133,1209,1210,1211,110000100134,110000100135,110000100136,110000100137,110000100138,1199,1198,110000100140,110000100141,110000100142,110000100154,110000100144,110000100145,110000100146,110000100147,110000100148,110000100149,110000100150,110000100469,110000100470,110000100472,110000100468,110000100471,110000100465,110000100466,110000100467,110000100151,110000100388,1027,1028,1029,40650000,1025,X001X38ZF1,110000100440,110000100439,110000100504,1187,110000100060,110000100707,110000100543,110000100694,1021,1054,110000100495,1033,110000100363,8034044828117,110000100438,110000100426,110000100425,110000100587,8034044828100,8034044828155,1076,1077,1078,1031,1053,1197,1243,110000100571,1236,1030,8034044838079,110000100435,8034044838062,110000100437,110000100695,110000100547,110000100546,110000100545,110000100548,110000100544,8034044838116,1032,1188,1190,1189,1191,1233,1234,1235,1237,110000100513,1023,196473749291,1026,1022,1024,196608848431,1196,1193,1195,1192,1194,110000100549,110000100550,110000100492,110000100494,110000100493,110000100491,110000100450,1017,110000100449,110000100579,1065,1020,1221,110000100139,1137', ','));

do $$
declare
  v_business uuid := '40b0fa9d-9ce6-4e17-902d-6f5f37cc58ab';
  v_n        int;
  v_list     text;
  v_items    int;
  v_insumos  int;
begin
  create temp table _tie_ids on commit drop as
  select mi.id, mi.name
  from public.menu_items mi
  join _tie_codigos c on c.codigo = mi.sku
  where mi.business_id = v_business;

  create temp table _tie_insumos on commit drop as
  select ii.id, ii.name
  from public.inventory_items ii
  join _tie_codigos c on c.codigo = ii.sku
  where ii.business_id = v_business;

  select count(*), string_agg(i.name, ', ')
    into v_n, v_list
  from _tie_ids i
  where exists (select 1 from public.order_items oi where oi.product_id = i.id);
  if v_n > 0 then
    raise exception
      'ABORTADO: % artículos ya tienen ventas (%). Desactívalos en vez de borrarlos.',
      v_n, v_list;
  end if;

  select count(distinct s.id), string_agg(distinct s.name, ', ')
    into v_n, v_list
  from _tie_insumos s
  join public.inventory_movements m on m.item_id = s.id;
  if v_n > 0 then
    raise exception
      'ABORTADO: % insumos ya tienen movimientos de inventario (%).', v_n, v_list;
  end if;

  select count(distinct s.id), string_agg(distinct s.name, ', ')
    into v_n, v_list
  from _tie_insumos s
  where exists (select 1 from public.physical_count_lines l where l.item_id = s.id)
     or exists (select 1 from public.recipe_ingredients ri where ri.inventory_item_id = s.id);
  if v_n > 0 then
    raise exception
      'ABORTADO: % insumos ya están en un conteo o en una receta (%).', v_n, v_list;
  end if;

  select string_agg(distinct s.name, ', ')
    into v_list
  from _tie_insumos s
  join public.menu_items mi on mi.inventory_item_id = s.id
  where mi.id not in (select id from _tie_ids);
  if v_list is not null then
    raise exception
      'ABORTADO: otros productos usan los insumos %. Quítaselos primero.', v_list;
  end if;

  delete from public.menu_item_links       x using _tie_ids i where x.item_id      = i.id;
  delete from public.menu_item_print_areas x using _tie_ids i where x.menu_item_id = i.id;
  delete from public.menu_item_taxes       x using _tie_ids i where x.item_id      = i.id;
  delete from public.menu_items           mi using _tie_ids i where mi.id          = i.id;
  get diagnostics v_items = row_count;

  delete from public.inventory_stock     st using _tie_insumos s where st.item_id = s.id;
  delete from public.inventory_items     ii using _tie_insumos s where ii.id      = s.id;
  get diagnostics v_insumos = row_count;

  delete from public.categories c
  where c.business_id = v_business
    and lower(btrim(c.name)) in ('pádel', 'fútbol', 'ropa y accesorios', 'servicios del club')
    and not exists (select 1 from public.menu_items m where m.category_id = c.id);

  raise notice 'Rollback: % artículos y % insumos borrados.', v_items, v_insumos;
end $$;

commit;

select
  (select count(*) from public.menu_items
     where business_id = '40b0fa9d-9ce6-4e17-902d-6f5f37cc58ab'::uuid) as productos_que_quedan,
  (select count(*) from public.inventory_items
     where business_id = '40b0fa9d-9ce6-4e17-902d-6f5f37cc58ab'::uuid) as insumos_que_quedan;
